    const followup=$("#career-discussion-followup-form");if(followup){const values=new FormData(followup),key=followup.dataset.stepId;data.discussion_followups={...data.discussion_followups,[key]:{...data.discussion_followups?.[key],question:values.get("question"),material_ids:values.getAll("material_ids"),selected_job_ids:values.getAll("selected_job_ids"),open:followup.closest("details").open}};}
