    try{const data=await api("career/work-relations?"+params);if(request!==career.work.request||location.hash!==route)return;career.work.data=data;root.innerHTML=workRelationsPage(data,filters);}catch(error){if(request===career.work.request&&location.hash===route)root.innerHTML=errorBox(error);}
