    $("#career-work-selection").innerHTML=workRelationsSelection();for(const button of $$("[data-work-rel-select]")){const active=selected.has(button.dataset.workRelSelect);button.setAttribute("aria-pressed",String(active));button.textContent=active?"移出对照":"加入两条关系对照";}
