    return {question:`「${jobText(job)}」两次保存的JD有哪些实质变化？请区分任务、交付物、责任和任职条件的变化、表述或补充说明，以及我们的分析变化；分别引用两侧原文，不外推行业趋势。`,why_matters:"判断岗位准备方向是否需要调整，区分来源内容变化与个人认识变化。",next_evidence:`核对这次选定的两份原文，而非后续最新两份。较早取得：${comparison.before.observed_at}；较晚取得：${comparison.after.observed_at}。使用read_historical_job分别按来源截止 ${comparison.before.read_as_of} 与来源截止 ${comparison.after.read_as_of} 读取，岗位ID ${job.id}。这些是本地观察与入库时间，不是网站发布时间。核对前后条件，允许两种解释并存；未读完、发布时间和实际分工未知处保持未知。`,hypothesis_a:"任务、交付物、责任或要求可能发生实质变化，仍待两侧原文和实际分工核实。",hypothesis_b:"差异可能来自表达改写或补充说明，未必意味着实际工作变化。",selected_job_ids:[job.id],source_passage:passageReference(before),after_passage:passageReference(after)};
