    try{const response=await api("career/"+id+"/experiments/cohorts",{method:"POST",body:JSON.stringify({...values,save})});draft.cohort_lab={...draft.cohort_lab,...values,open:true,result:{...response.experiment,hypothesis:values.hypothesis},saved_task_id:response.task_id||null};career.drafts.set(id,draft);if(career.id===id&&response.career)career.data=response.career;notify(save?"分群指标计算已保存到练习板。":"本机计算完成，可对照总体、分群与人群占比。");}
