  function experimentWorkspaceRecords(task,data){
    const includes=row=>row.task_id===task.id||row.experiment_ids?.includes(task.id)||row.result?.career_learning_context?.selected_experiments?.some(item=>item.id===task.id),associated=data.results.filter(includes),source=data.results.find(row=>row.step_id===task.source_step_id||row.run_id&&task.source_key?.startsWith(row.run_id+":")),studies=[...associated];if(source&&!studies.includes(source))studies.push(source);
    return {studies:studies.sort((a,b)=>(b.created_at||"").localeCompare(a.created_at||"")),notes:(data.insights||[]).filter(note=>note.task_id===task.id||associated.some(row=>row.step_id===note.source_step_id)),previous:data.tasks.find(row=>row.id===task.previous_task_id),children:data.tasks.filter(row=>row.previous_task_id===task.id)};
  }
