    return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>我的回答对照</title><style>body{font-family:system-ui,"Microsoft YaHei",sans-serif;line-height:1.8;color:#26352f;background:#f7f8f5;margin:0}main{max-width:1100px;margin:24px auto;padding:28px;background:white}h1{font-size:24px}h4{margin-bottom:8px}.form-note{font-size:12px;color:#68776a}p,blockquote{white-space:pre-wrap;overflow-wrap:anywhere}.career-answer-comparison{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.career-answer-comparison-column{min-width:0;border:1px solid #dbe3d8;padding:18px}.career-comparison-claim{border-top:1px solid #dbe3d8;padding:12px 0}blockquote{margin:12px 0;padding:12px;background:#f4f7f1}details{margin:14px 0}@media(max-width:700px){main{margin:0;padding:16px}.career-answer-comparison{grid-template-columns:1fr}}</style></head><body><main><p>${e(data.title)} · ${e(interviewFocusLabel(source,data))}</p><h1>${e(question)}</h1><p class="form-note">来自用户保存的原回答与研究反馈。两次条件可能不同，较新不表示更正确；反馈仍需原文核实，回答不证明实际经历或能力。${demoMode?"预置脚本与虚构资料演示。":""}</p><div class="career-answer-comparison">${pair.map((row,n)=>answerReplayColumn(row,n,true)).join("")}</div></main></body></html>`;
