    const preparingNote=!selected&&draft.interview_focus?.startsWith("insight:");
    return `<div class="section-heading"><div><h2>${selected?.understanding_check||preparingNote?"把理解讲清楚，再检查边界":"让真实经历经得住追问"}</h2><p class="form-note">${selected?.understanding_check||preparingNote?"先用自己的话解释，再对照原文检查推理、反例与未知。这里的回答不是做过项目的证明。":"先回答，再根据真实回答追问；也可以重答同一道题，回看表达与证据的变化。"}</p></div></div>${interviewFocusPanel(data)}${selected?`<form id="career-interview-answer" class="panel career-answer-form" data-source-step="${e(selected.step_id)}" data-question-index="${index}"><p class="form-note career-interview-source">本组问题围绕：${e(interviewFocusLabel(selected,data))}</p>${selected.story_id&&data.stories.some(story=>story.id===selected.story_id)?`<a class="text-button" href="#career/${e(data.id)}/story/${e(selected.story_id)}">回看这份经历与面试准备 ↗</a>`:""}<div class="form-grid"><label>本次练习哪组问题<select name="source_step_id">${sources.map(row=>`<option value="${e(row.step_id)}" ${row===selected?"selected":""}>${e(interviewFocusLabel(row,data))} · ${row.kind==="ask"?"对照两次回答的追问":row.kind==="followup"?"针对回答的追问":row.understanding_check?"理解自测":"岗位模拟面试"} · ${e(when(row.created_at))}</option>`).join("")}</select></label><label>选择本次回答的问题<select name="question_index">${questions.map((text,n)=>`<option value="${n}" ${index===n?"selected":""}>${n+1}. ${e(text)}</option>`).join("")}</select></label></div>${interviewProgress(selected,index,data,counts,next)}<blockquote class="career-active-question">${e(questions[index])}</blockquote>${interviewQuestionContext(selected,index,data)}<label>${selected?.understanding_check?"用自己的话解释（允许说不知道）":"写下你的真实回答"}<textarea id="career-answer" name="answer" rows="6" maxlength="2500" required placeholder="${selected?.understanding_check?"用自己的话解释为什么、适用条件是什么；可以明确写不知道或尚未验证，不必编造实际经历。":"写实际行动、当时的选择、验证方法，以及你还说不清的部分。"}">${e(answer)}</textarea></label><button class="primary" ${researchUnavailable(data)?"disabled":""}>${selected.understanding_check?"检查我的理解与推理":"结合原文反馈我的回答"} ↗</button></form>${answerReplay(selected,index,data)}`:preparingNote?empty("从一条认识开始练习","先生成自测问题，再用自己的话回答；可以明确说不知道或尚未验证。"):draft.interview_focus?empty("这份材料还没有可练的题组","可以从上方为它准备问题，或切换到综合材料查看其他已存题组。没有自动开始模型调用。"):empty("从你的材料出发的一次模拟面试","先补充一份经历，或直接准备面试问题；缺少的信息会明确指出。")}`;
