    if(saved){if(draft.pitch?.id!==pitchId)draft.pitch={...saved};}
    else if(source){draft.pitch={...(draft.pitch||{}),title:draft.pitch?.title||((story?.title||"项目")+" · 面试讲述").slice(0,150),story_id:source.story_id||"",source_step_id:source.step_id,text:source.result.claims.map(claim=>claim.text).join("\n\n")};}
    else if(!draft.pitch){draft.pitch={title:story?(story.title+" · 面试讲述").slice(0,150):"",story_id:story?.id||"",source_step_id:"",text:story?"背景和目标："+story.situation+"\n\n我的行动："+story.action+"\n\n结果与证据："+story.result+"\n\n尚未做到或未参与："+(story.limits||"请补充实际边界") :""};}
