    const observed=(row.result.evidence||[]).map(ev=>ev.title+"："+ev.quote).join("\n\n"),unknowns=(row.result.gaps||[]).filter(text=>!text.startsWith("静态有限样本")).join("\n");
    const long=previous.length>1500||observed.length>2000||unknowns.length>1000;
