    return `<section class="career-autonomy"><strong>连续查证 · 第 ${4-row.autonomous_rounds} / 3 轮</strong>${reason?`<details><summary>Agent 为什么接着查这个问题</summary><p>${e(reason.evidence_needed)}</p><p><strong>本轮希望回答：</strong>${e(reason.completion)}</p></details>`:""}${row.autonomous_stop?`<p>${e(row.autonomous_stop)}</p>`:""}${exporting?"":`<a class="text-button" href="#career/${e(career.id)}/batch/${e(row.step_id)}">回看整批调查怎样推进 ↗</a>`}</section>`;
