    return `<aside class="career-discussion-learning" data-discussion-learning="${e(row.step_id)}:${index===null?"whole":index}"><h4>${index===null?"我对整次研究保存的理解":"我对这条判断保存的认识"}</h4><p class="form-note">这些是你保存的理解及其后续接替记录，仍需核对依据。原答复保留；选用、接替和记录较新都不代表已经证实。</p>${active.map(card).join("")||'<p class="form-note">目前没有选用中的关联认识，可以展开已搁置记录回看。</p>'}${parked.length?`<details class="career-discussion-parked"><summary>已搁置的相关认识 · ${parked.length} 份</summary>${parked.map(card).join("")}</details>`:""}</aside>`;
