    const picked=(storyDraft().passage_comparisons?.[question.id]?.ids||[]).filter(id=>passages.some(row=>row.id===id));
    const filter=exporting?"all":storyDraft().passage_filters?.[question.id]||"all",groups=passageGroups(question),hasViews=Boolean(question.hypothesis_a||question.hypothesis_b);
    const card=(row,showTarget=true)=>`<article class="career-collected-passage" data-question-passage="${e(row.id)}">${!exporting&&!demoMode?`<label class="career-passage-pick"><input type="checkbox" data-career-passage-compare="${e(question.id)}" value="${e(row.id)}" ${picked.includes(row.id)?"checked":""}>加入摘录对照</label>`:""}<span class="quiet-tag">我的标注：${e(passageRelations[row.relation]||passageRelations.unclassified)}</span>${!showTarget?"":row.target_view?`<p class="career-passage-target"><strong>标注针对的解释原句：</strong>${e(row.target_view)}</p>${hasViews&&![question.hypothesis_a,question.hypothesis_b].includes(row.target_view)?'<p class="form-note">这句话不同于当前 A、B 的表述，原标注未自动转给新解释。</p>':""}`:'<p class="form-note">尚未注明具体针对哪句解释；先保留线索，再核对其含义。</p>'}${row.user_note?`<p><strong>为什么值得带回：</strong>${e(row.user_note)}</p>`:""}${passageOrigin({source_passage:row},data,exporting,"所收集的原文与出处")}${exporting?"":`<div class="result-actions">${!demoMode?`<button type="button" class="secondary small" data-career-passage-insight="${e(question.id)}:${e(row.id)}">写下这段原文带来的理解 ↗</button>`:""}<button type="button" class="text-button" data-career-edit-passage="${e(question.id)}:${e(row.id)}">修改我的标注</button><button type="button" class="text-button" data-career-remove-passage="${e(question.id)}:${e(row.id)}">从这个问题移除摘录</button></div>`}</article>`;
    const grouped=hasViews?`<p class="form-note">按标注时针对的原句对照，先看条件与出处。摘录条数不代表独立来源数量，不能靠条数选出更好的解释。</p><div class="career-passage-hypotheses">${groups.filter(group=>group.view).map(group=>`<section data-passage-group="${group.id}"><h4>${e(group.label)}</h4><p class="career-passage-view">${e(group.view)}</p>${passageEvidenceSummary(group)}${group.passages.filter(row=>filter==="all"||row.relation===filter).map(row=>card(row,false)).join("")||`<p class="form-note">${group.passages.length?"当前筛选下没有标注；其他标注仍保留。":"还没有明确针对这句话的摘录，可从原文中继续收集。"}</p>`}</section>`).join("")}</div>${groups.filter(group=>!group.view).map(group=>`<section data-passage-group="other"><h4>${e(group.label)}</h4>${group.passages.filter(row=>filter==="all"||row.relation===filter).map(row=>card(row)).join("")||'<p class="form-note">当前筛选下没有其他摘录，旧标注仍保留。</p>'}</section>`).join("")}`:passages.filter(row=>filter==="all"||row.relation===filter).map(row=>card(row)).join("");
