    const findings=row.result.claims.map(claim=>(labels[claim.basis]||"待核对判断")+(claim.requirement&&claim.requirement!=="unspecified"?"（"+(requirementLabels[claim.requirement]||"性质待核")+"）":"")+"："+claim.text).join("\n\n");
