    const side=(entries,name)=>`<section><h5>${name}</h5>${entries.length?entries.map(({index,relation,row})=>{const used=new Set((relation.claim_indices||[]).flatMap(index=>row.result.claims[index]?.evidence_ids||[]));return `<p class="form-note">第 ${index+1} 条关系 · ${e(({direct:"原文明示",synthesis:"归纳",inference:"待验证解释"})[relation.basis]||"性质待核")}</p><p><strong>为什么关联：</strong>${e(relation.rationale)}</p><p><strong>迁移限制：</strong>${e(relation.transfer_limit)}</p><details ${exporting?"open":""}><summary>当时绑定的判断与引用</summary>${(relation.claim_indices||[]).map(index=>{const claim=row.result.claims[index];return claim?`<p>${e(claim.text)}</p><p class="form-note">${e(claimBasisLabel(claim))} · ${e(requirementLabels[claim.requirement]||"性质未说明")}</p>`:""}).join("")}${(row.result.evidence||[]).filter(source=>used.has(source.id)).map(source=>`<p class="form-note">${e(source.title)} · 当时保存的引用</p><blockquote>${e(source.quote)}</blockquote>${exporting?"":sourceContextButton(source)}`).join("")}</details>`}).join(""):'<p class="form-note">没有找到完全同文的关系；可能是改写、范围不同或没有表达，不能据此认定已经撤回或新增工作事实。</p>'}</section>`;
