    const quote=source=>`<details class="career-comparison-quote"><summary>${e(source.label)} · ${e(source.title)} · ${["search_answer","search_excerpt"].includes(source.evidence_kind)?"搜索线索，未核正文":"保存的引用片段"}</summary><p class="form-note">原文字符 ${source.start}–${source.end}，当时保存的引用，不是本次重新读取。</p><blockquote>${e(source.quote)}</blockquote>${interactive?sourceContextButton(source):archiveSourceLink(source,archive)}</details>`;
    const used=new Set(row.result.claims.flatMap(claim=>claim.evidence_ids));
