  const investigationArchiveScript=`(()=>{"use strict";document.addEventListener("click",event=>{const link=event.target.closest('a[href^="#archive-"]');if(!link)return;const target=document.getElementById(link.getAttribute("href").slice(1));if(!target)return;for(let node=target;node;node=node.parentElement)if(node.tagName==="DETAILS")node.open=true;requestAnimationFrame(()=>target.scrollIntoView({block:"start"}));});for(const form of document.querySelectorAll(".archive-find")){let previous="",cursor=-1;const search=direction=>{const body=form.closest(".archive-source").querySelector(".archive-source-text"),query=form.elements.query.value.trim(),status=form.querySelector("output");if(!query){status.textContent="请输入关键词";return;}const nodes=[],walker=document.createTreeWalker(body,NodeFilter.SHOW_TEXT);let node,text="";while(node=walker.nextNode()){nodes.push({node,start:text.length,end:text.length+node.textContent.length});text+=node.textContent;}const hits=[];for(let at=0;(at=text.indexOf(query,at))>=0;at+=Math.max(1,query.length))hits.push(at);if(!hits.length){status.textContent="未找到";window.getSelection()?.removeAllRanges();return;}cursor=query!==previous?direction<0?hits.length-1:0:(cursor+direction+hits.length)%hits.length;previous=query;const start=hits[cursor],end=start+query.length,first=nodes.find(item=>item.end>start),last=nodes.find(item=>item.end>=end&&item.start<end),range=document.createRange();range.setStart(first.node,start-first.start);range.setEnd(last.node,end-last.start);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);const rect=range.getBoundingClientRect();window.scrollBy(0,rect.top-100);status.textContent=(cursor+1)+" / "+hits.length;};form.addEventListener("submit",event=>{event.preventDefault();search(1);});form.querySelector("[data-archive-prev]").addEventListener("click",()=>search(-1));}})();`;
