    const attribute=action.kind==="observation"?`data-career-observation-inquiry="${e(action.id)}"`:action.kind==="conclusion"?`data-career-conclusion-draft="${e(question.id)}:${e(action.id)}"`:`${focus?"data-career-focus-continue":"data-career-question-ask"}="${e(question.id)}"`;
