        const row=rows[index],status=row.querySelector("[data-comparison-start-status]");if(row.dataset.savedJobId)continue;
        status.textContent="正在保存这份岗位原文…";const saved=await api("import",{method:"POST",body:JSON.stringify(values[index])});row.dataset.savedJobId=saved.job_id;status.textContent="这份JD已保存，本次会继续使用它。";row.querySelector("[data-comparison-start-edit]").hidden=false;
