    if(kind==="history"&&/^[a-f0-9]{32}$/.test(id)){if(!career.data.questions?.some(row=>row.id===id)){notify("这个问题已不在当前目标中，可以重新选择。");return;}captureDrafts();storyDraft().result_view="question:"+id;career.tab="requirements";renderDetail();$(".career-result-area").scrollIntoView({block:"start",behavior:"smooth"});return;}
    if(kind==="practice"&&/^[a-f0-9]{32}$/.test(id)){prepareNotePractice(id);return;}
