      if(entry.tool==="run_retry_experiment"&&Number.isInteger(entry.case_count))detail=`本机顺序计算 ${entry.case_count} 组、${entry.request_count} 条输入；不连接真实服务。`;
      if(entry.tool==="plan_investigation")detail=(entry.replanned?"调整调查：":"调查拆解：")+(entry.questions||[]).join("；")+" · "+(entry.retrieval_attempts||[]).length+" 组本地查询";
      if(entry.terms?.length)detail="检索词："+entry.terms.join("、");
      if(Number.isInteger(entry.matched))detail+=(detail?" · ":"")+"命中 "+entry.matched+" 条记录";
      if(Number.isInteger(entry.map_matches)&&entry.map_matches)detail+=" · 涉及 "+entry.map_matches+" 处地图内容";
      if(entry.windows?.length)detail="读取 "+entry.windows.length+" 段："+[...new Set(entry.windows.map(item=>original(item.document_id,item.job_id)))].join("、")+(entry.windows.some(item=>item.has_more)?"；部分正文仍有未读内容。":"");
      else if(entry.public_document_id||entry.job_id)detail=original(entry.public_document_id,entry.job_id);
      if(entry.step_id){const old=data.results?.find(item=>item.step_id===entry.step_id);detail=old?.user_question||old?.interview_question||"本目标中的一份旧研究";href=`#career/${data.id}/discussion/${entry.step_id}`;}
      if(entry.question_id){const question=row.result?.career_learning_context?.read_inquiries?.find(item=>item.id===entry.question_id)||data.questions?.find(item=>item.id===entry.question_id);detail=question?.question||"本目标中的一条调查笔记";href=`#career/${data.id}/investigate/${entry.question_id}`;}
      if(entry.note_id){const note=row.result?.career_learning_context?.read_notes?.find(item=>item.id===entry.note_id)||data.insights?.find(item=>item.id===entry.note_id);detail=note?.current_user_view||note?.current_view||"本目标中的一份认识";href=`#career/${data.id}/insight/${entry.note_id}`;}
      if(entry.experiment_ids?.length)detail=entry.experiment_ids.map(id=>data.tasks?.find(item=>item.id===id)?.title||"留存实验记录").join("、");
