    return {...origin,title:"检验这项调查解释",task_or_ability:"",hypothesis:"",deliverable:"",completion_check:"",comparison_conditions:"",comparison_rows:[{condition:"解释预计成立的条件",input:"",expected:"",observed:""},{condition:"改变条件或寻找反例",input:"",expected:"",observed:""}]};
