    return `<section class="panel career-investigation-next" data-investigation-next="${e(next.kind)}"><span class="eyebrow">KEEP ONE QUESTION MOVING</span><h3>${e(next.label)}</h3><p>${e(next.reason)}</p><div class="result-actions">${inquiryNextButton(next,question,data)}<button type="button" class="text-button" data-career-investigation-compose>编辑这次想问的问题 ↓</button></div><div class="career-investigation-alternatives"><span>也可以先自己推进：</span><button type="button" class="text-button" data-career-question-experiment="${e(question.id)}">设计一个小验证 ↗</button><button type="button" class="text-button" data-career-edit-question="${e(question.id)}">记下我的解释与未知 ↗</button>${!demoMode?`<a class="text-button" href="#career/${e(data.id)}/answer-question/${e(question.id)}">用自己的话解释一次 ↗</a>`:""}</div></section>${question.conclusion?`<section class="panel career-investigation-view"><h3>我已保存的解释与限制</h3><p>${e(question.conclusion)}</p><p class="form-note">用户记录于 ${e(when(question.updated_at||question.created_at))}，仍可结合新材料修订。</p><button type="button" class="text-button" data-career-edit-question="${e(question.id)}">继续修改这份解释 ↗</button></section>`:""}${notes.length||tasks.length?`<section class="panel career-investigation-recent"><h3>最近保存的观察与认识</h3><ul>${tasks.slice(0,2).map(task=>`<li><a href="#career/${e(data.id)}/task/${e(task.id)}">${e(task.title)} ↗</a><span class="form-note">${e(taskStates[task.state]||task.state)} · ${experimentHasObservations(task)?"已有用户记录的观察":"尚无实际观察"}</span></li>`).join("")}${notes.slice(0,2).map(note=>`<li><a href="#career/${e(data.id)}/understanding/${e(note.id)}">回看个人认识 · ${e(when(note.updated_at||note.created_at))} ↗</a><span class="form-note">${note.use_for_research===false?"已搁置":"选用于后续研究"}</span></li>`).join("")}</ul><p class="form-note">按最近保存时间列出入口。完整原话、反例和其他记录可在下方调查背景与历史中回看。</p></section>`:""}`;
