  async function runPreparedResearch(id,stepId,fromRoute,batchId=null){
    const readingRoute=career.id===id&&location.hash===fromRoute?"#career/"+id+"/"+(batchId?"batch/"+batchId:"discussion/"+stepId):null;
    if(readingRoute){captureDrafts();if(location.hash!==readingRoute)history.pushState(null,"",readingRoute);career.workspaceExpanded=false;}
    try{await api("projects/"+id+"/run",{method:"POST",body:JSON.stringify({step_id:stepId})});}
    finally{
      if(readingRoute&&career.id===id&&location.hash===readingRoute){await openCareer(id,null);if(career.id===id&&location.hash===readingRoute)focusCareerRecord(batchId?"batch":"discussion",batchId||stepId);}
    }
  }
  async function research(kind,answer="",questionIndex=0,taskId=null,sourceStepId=null,question="",extras={}){
    if(career.busy)return;if(["role","map"].includes(kind)&&storyDraft().proof){notify("先保存或取消正在编辑的证据对照，再重新分析岗位。");return;}captureDrafts();
    if(kind==="interview"){const [focus,id]=(storyDraft().interview_focus||"").split(":");if(focus==="insight"){kind="teachback";extras={...extras,insight_id:id};}else extras={...extras,...(focus==="story"?{story_id:id}:focus==="task"?{task_id:id}:{})};}
    career.busy=true;renderDetail();
    const id=career.id,fromRoute=location.hash;
    try{
      if(demoMode){extras={...extras};delete extras.claim_review_index;delete extras.passage_ids;delete extras.inquiry_answer;delete extras.experiment_ids;}
      const step=await api("career/"+id+"/prepare",{method:"POST",body:JSON.stringify({adaptive:kind==="ask"&&!demoMode&&!career.offline,kind,answer,question_index:questionIndex,task_id:taskId,source_step_id:sourceStepId,question,section:career.tab,offline:Boolean(career.offline),allow_public:Boolean(storyDraft().allow_public)&&!career.offline&&!demoMode,...extras})});
      if(["interview","teachback","followup"].includes(kind)||kind==="ask"&&career.tab==="interview"&&extras.comparison_step_ids?.length===2){const draft=career.drafts.get(id)||{};draft.next_source_step_id=step.step_id;draft.question_index="0";career.drafts.set(id,draft);}
      await runPreparedResearch(id,step.step_id,fromRoute,extras.autonomous?step.step_id:null);
      return step;
    }catch(error){notify(error.message,true);}
    finally{career.busy=false;if(career.data?.id===career.id){captureDrafts();renderDetail();}}
  }

